with latest as (select id, account_id, txn_time, merchant from transactions qualify row_number() over (partition by txn_type, merchant order by amount, id) = 1), deduped as (select * from (select *, row_number() over (partition by account_id, merchant order by txn_time, id) as rn from latest) ranked where rn = 1), ranked as (select *, rank() over (partition by account_id order by txn_time desc) as rank_in_group from deduped qualify rank_in_group = 1), deduped_transactions as (select *, row_number() over (partition by account_id order by txn_time desc, id) as rn_2 from ranked qualify rn_2 = 1), joined as (select s.*, a.status from deduped_transactions s left join accounts a on s.account_id = a.id) select id, txn_time, rn, rank_in_group, rn_2, status, row_number() over (partition by year(txn_time), merchant order by rank_in_group, id) as row_seq, row_number() over (partition by merchant, status order by rn_2 desc, id) as row_seq_2 from joined
